head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF91010";
scwin.dom_forn_isu_tp_cd = null;
scwin.id_reg_button = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — cfiCdGroupList5, cfiCdGroupList6, stdCdApctTpCdList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dom_forn_isu_tp_cd = $c.util.getComponent('dom_forn_isu_tp_cd');
        scwin.id_reg_button = $c.util.getComponent('id_reg_button');
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf91010.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_oldStkcertIsuTpContn_txt", fn: function(){ return ((dma_map.get("oldStkcertIsuTpContn") ?? (() => { throw new Error("unresolved:" + "map.oldStkcertIsuTpContn"); })()) !== ''); } }, { id: "if_fornSecuKindNm_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) !== '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) !== ''); } }, { id: "if_fornSecuKindNm_2_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) !== '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) === ''); } }, { id: "if_fornSecuKindNm_3_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) === '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) !== ''); } }, { id: "rd_group", fn: function(){ return (!(String(((dma_pageContext.get("cfiCdGroupList5") ?? "")) == null ? '' : ((dma_pageContext.get("cfiCdGroupList5") ?? ""))).length === 0)); } }, { id: "rd_group_2", fn: function(){ return (!(String(((dma_pageContext.get("cfiCdGroupList6") ?? "")) == null ? '' : ((dma_pageContext.get("cfiCdGroupList6") ?? ""))).length === 0)); } }, { id: "rd_stdCdApctTpCd", fn: function(){ return (!(String(((dma_pageContext.get("stdCdApctTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("stdCdApctTpCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "(" + String(dma_map.get("isurCd")) + ") " + String(dma_map.get("comNm")); } },
        { childId: "__rb6", fn: function () { return String(dma_map.get("domFornStkcertTpNm")) + "주권"; } },
        { childId: "__rb10", fn: function () { return String(dma_map.get("fornSecuKindNm")) + "&nbsp;&nbsp;(발행일:" + String(dma_map.get("fornSecuIsuDate")) + ")"; } },
        { childId: "__rb12", fn: function () { return "발행일:" + String(dma_map.get("fornSecuIsuDate")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.checkRegData();
        $("#group_C").attr("disabled", true);
        $("#group_Y").attr("disabled", true);
        scwin.setCfi();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91010.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_Chk_form();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91010.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91010.btn_mpd_files_del_onclick' }); }
};

