///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Chk_form
 * @description Chk form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Chk_form = async function () {
    const sbmOptions = {
        id: "tx_Chk_form",
        method: "post",
        action: "/stdcd/mfStkcert.do?method=stockModifyProcess",
        ref: "dma_ChkFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name checkRadio
 * @description check Radio 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkRadio = function () {
    const checkRdArr = $('input[key=checkRd]');
    const leng = checkRdArr.length;
    if (leng > 0) {
        for (let i = 0; i < leng; i++) {
            const vl = $(checkRdArr[i]).val();
            const target = $(checkRdArr[i]).attr("target");
            const checkId = $('label[for*=' + target + ']:contains(' + vl + ')').attr("for");
            const tObj = $('#' + checkId);
            if (tObj.length > 0) {
                $('#' + checkId)[0].checked = true;
            }
        }
    }
};

/**
 * @method
 * @name checkSelect
 * @description check Select 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkSelect = function () {
    const checkStArr = $('input[key=checkSt]');
    const leng = checkStArr.length;
    if (leng > 0) {
        for (let i = 0; i < leng; i++) {
            const vl = $(checkStArr[i]).val();
            const target = $(checkStArr[i]).attr("target");
            const tObj = $('#' + target);
            if (tObj.length > 0) {
                $('#' + target).find('option:contains(' + vl + ')').attr("selected", true);
            }
        }
    }
};

/**
 * @method
 * @name checkRegData
 * @description check Reg Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkRegData = function () {
    const vl = dma_hiddenStore.get("regType");
    const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
    if (tObj.length > 0) {
        $(tObj)[0].checked = true;
    }
    const email = $c.util.getComponent('ipt_encrypApctEmail').getValue();
    const emails = email.split("@");
    if (emails.length > 0) {
        $c.util.getComponent('ipt_encrypApctEmail1').setValue(emails[0]);
    }
    if (emails.length > 1) {
        $c.util.getComponent('ipt_encrypApctEmail2').setValue(emails[1]);
    }
    const tel = $c.util.getComponent('ipt_apctTelNo').getValue();
    const tels = tel.split("-");
    if (tels.length > 0) {
        $c.util.getComponent('ipt_apctTelNo1').setValue(tels[0]);
    }
    if (tels.length > 1) {
        $c.util.getComponent('ipt_apctTelNo2').setValue(tels[1]);
    }
    if (tels.length > 2) {
        $c.util.getComponent('ipt_apctTelNo3').setValue(tels[2]);
    }
    const fax = $c.util.getComponent('ipt_apctFaxNo').getValue();
    const faxs = fax.split("-");
    if (faxs.length > 0) {
        $c.util.getComponent('ipt_apctFaxNo1').setValue(faxs[0]);
    }
    if (faxs.length > 1) {
        $c.util.getComponent('ipt_apctFaxNo2').setValue(faxs[1]);
    }
    if (faxs.length > 2) {
        $c.util.getComponent('ipt_apctFaxNo3').setValue(faxs[2]);
    }
    const hpNo = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
    const hpNos = hpNo.split("-");
    if (hpNos.length > 0) {
        $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(hpNos[0]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(hpNos[1]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(hpNos[2]);
    }
};

/**
 * @method
 * @name chk_mod_text
 * @description chk mod text 처리
 * @param {String} str str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_mod_text = async function (str) {
    const len = $c.str.getByteLength(str);
    if (str === "") {
        await $c.win.alert("수정사유를 입력하세요");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    if (len < 10) {
        await $c.win.alert("수정사유는 한글 5자, 영문 10자 이상 입력하세요");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    if (len > 60) {
        await $c.win.alert("수정사유는 한글30자, 영문60자 이내로 입력하세요.");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name deActivateRelatedTF
 * @description de Activate Related TF 처리
 * @param {*} objArr objArr
 * @param {*} isDisable isDisable
 * @returns {void}
 * @hidden N
 */
scwin.deActivateRelatedTF = function (objArr, isDisable) {
    for (let i = 0; i < objArr.length; i++) {
        if (objArr[i].disabled = isDisable) {
            objArr[i].style.background = "#e2e2e2";
            objArr[i].style.borderStyle = "solid";
        } else {
            objArr[i].style.background = "#FFFFFF";
            objArr[i].style.borderStyle = "solid";
        }
    }
};

