/**
 * @method
 * @name makeFisn
 * @description make Fisn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.makeFisn = async function () {
    const com_attr_tp_cd = '' + dma_companyInfoVO.get("comAttrTpCd") + '';
    if (com_attr_tp_cd !== "5" && com_attr_tp_cd !== "7") {
        $c.util.getComponent("ipt_comEngAbbrv").setValue(fn_cut_spacingWords($c.util.getComponent('ipt_comEngAbbrv').getValue(), 15));  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_cut_spacingWords — as-is 공통(폼 전역 의존) — 반입 보류
    }
    const thisForm = $('#JLDINF10000');
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    const v_group = $('input[name=group]:checked').val();
    let temp = "";
    temp += $c.util.getComponent('ipt_comEngAbbrv').getValue();
    if (v_group === 'S' || v_group === 'C' || v_group === 'Y' || v_group === 'M') {
        temp += "/Com Sh";
        if ($c.util.getComponent('slc_attr01').getValue() === "N") {
            temp += " NVTG";
        }
        if ($c.util.getComponent('slc_attr03').getValue() === "P") {
            temp += " PP";
        }
        if ($c.util.getComponent('slc_attr02').getValue() === "T") {
            temp += " Rstd";
        } else {
            if ($c.util.getComponent('slc_attr02').getValue() === "U") {
                temp += " Unrestr";
            }
        }
        if ($c.util.getComponent('slc_currTpCd').getValue() === "1") {
            temp += " " + "" + dma_map.get("par_amt") + "";
        } else {
            temp += " " + "" + dma_map.get("par_amt") + "";
        }
    } else {
        if (v_group === 'P' || v_group === 'F') {
            if ($('input[name=group]:checked').val() === "F") {
                temp += "/Cv";
            } else {
                temp += "/";
            }
            temp += " Pref";
        } else {
            if (v_group === 'I' || v_group === 'B' || v_group === 'E') {
                if ($('input[name=group]:checked').val() === "B") {
                    temp += "/CIV REIT";
                } else {
                    if ($('input[name=group]:checked').val() === "E") {
                        temp += "/CIV ETF";
                    } else {
                        if ($('input[name=group]:checked').val() === "I") {
                            temp += "/CIV";
                        }
                    }
                }
                if ($c.util.getComponent('slc_currTpCd').getValue() === "1") {
                    temp += " KRW";
                } else {
                    if ($c.util.getComponent('slc_currTpCd').getValue() === "2") {
                        temp += " USD";
                    } else {
                        if ($c.util.getComponent('slc_currTpCd').getValue() === "3") {
                            temp += " JPY";
                        } else {
                            if ($c.util.getComponent('slc_currTpCd').getValue() === "4") {
                                temp += " EUR";
                            } else {
                                if ($c.util.getComponent('slc_currTpCd').getValue() === "5") {
                                    temp += " CNY";
                                } else {
                                    if ($c.util.getComponent('slc_currTpCd').getValue() === "6") {
                                        temp += " GBP";
                                    } else {
                                        if ($c.util.getComponent('slc_currTpCd').getValue() === "7") {
                                            temp += " HKD";
                                        } else {
                                            if ($c.util.getComponent('slc_currTpCd').getValue() === "8") {
                                                temp += " AUD";
                                            } else {
                                                if ($c.util.getComponent('slc_currTpCd').getValue() === "9") {
                                                    temp += " SGD";
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                if (v_group === 'L') {
                    temp += "/Ltd Pshp";
                    if ($c.util.getComponent('slc_attr03').getValue() === "O") {
                        temp += " Nl Pd";
                    } else {
                        if ($c.util.getComponent('slc_attr03').getValue() === "P") {
                            temp += " PP";
                        } else {
                            if ($c.util.getComponent('slc_attr03').getValue() === "F") {
                                temp += " FPd";
                            }
                        }
                    }
                    if ($c.util.getComponent('slc_currTpCd').getValue() === "1") {
                        temp += " KRW";
                    } else {
                        if ($c.util.getComponent('slc_currTpCd').getValue() === "2") {
                            temp += " USD";
                        } else {
                            if ($c.util.getComponent('slc_currTpCd').getValue() === "3") {
                                temp += " JPY";
                            } else {
                                if ($c.util.getComponent('slc_currTpCd').getValue() === "4") {
                                    temp += " EUR";
                                } else {
                                    if ($c.util.getComponent('slc_currTpCd').getValue() === "5") {
                                        temp += " CNY";
                                    } else {
                                        if ($c.util.getComponent('slc_currTpCd').getValue() === "6") {
                                            temp += " GBP";
                                        } else {
                                            if ($c.util.getComponent('slc_currTpCd').getValue() === "7") {
                                                temp += " HKD";
                                            } else {
                                                if ($c.util.getComponent('slc_currTpCd').getValue() === "8") {
                                                    temp += " AUD";
                                                } else {
                                                    if ($c.util.getComponent('slc_currTpCd').getValue() === "9") {
                                                        temp += " SGD";
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if (com_attr_tp_cd === "5" || com_attr_tp_cd === "7") {
        if ($c.util.getComponent('ipt_comEngAbbrv').getValue().length > 27) {
            temp = fn_cut_spacingWords(temp, 35);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_cut_spacingWords — as-is 공통(폼 전역 의존) — 반입 보류
        }
    }
    $c.util.getComponent('ipt_fisnVal').setValue(fn_cut_spacingWords(temp, 35));  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_cut_spacingWords — as-is 공통(폼 전역 의존) — 반입 보류
    $c.util.getComponent('ipt_fisnVal').setValue(($c.util.getComponent("ipt_fisnVal").getValue() || '').toUpperCase());
    $c.util.getComponent('ipt_fisnMakeYn').setValue("Y");
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
};
